/**
 * ADR-FE-016 — What the dungeon sounds like: each cue the explorer can play,
 * and the file(s) behind it in `public/audio/dungeon/` (names without extension,
 * as `AudioEngine` expects them). Several files are variants: one is drawn at
 * random each time, so repeated steps do not sound mechanical.
 *
 * Every file is CC0 or generated by the squad, and listed in
 * `public/audio/CREDITS.md`.
 */

export type DungeonCue =
  /** The hero takes a step (predicted, played before the server answers). */
  | "step"
  /** A refused move: a wall, an obstacle, a mob in the way. */
  | "bump"
  /** Walking into the gate while the boss still stands. */
  | "gateLocked"
  /** The boss of a floor is defeated and its gate opens. */
  | "gateOpen"
  /** The final boss is defeated: the run is won. */
  | "victory"
  /** Down the gate, onto the next floor. */
  | "floorDown"
  /** The party enters a room it had not discovered yet. */
  | "roomDiscovered";

export interface CueSound {
  files: readonly string[];
  /** Relative to the effects bus, 0 to 1. */
  volume: number;
}

export const DUNGEON_CUES: Readonly<Record<DungeonCue, CueSound>> = {
  step: {
    files: Array.from({ length: 10 }, (_, i) => `dungeon/step-${i + 1}`),
    volume: 0.5,
  },
  bump: { files: ["dungeon/bump"], volume: 0.6 },
  gateLocked: { files: ["dungeon/gate-locked"], volume: 0.7 },
  gateOpen: { files: ["dungeon/gate-open"], volume: 0.9 },
  victory: { files: ["dungeon/victory"], volume: 0.9 },
  floorDown: { files: ["dungeon/floor-down"], volume: 0.8 },
  // Barely there on purpose: noticed only when it is missing.
  roomDiscovered: {
    files: [
      "dungeon/room-discovered-1",
      "dungeon/room-discovered-2",
      "dungeon/room-discovered-3",
    ],
    volume: 0.35,
  },
};

/** One loop for every floor theme in v1 (ADR-FE-016). */
export const DUNGEON_AMBIENCE = { file: "dungeon/ambience", volume: 1 } as const;

/** Every effect file, preloaded on the first gesture; the ambience loads after. */
export const DUNGEON_EFFECT_FILES: readonly string[] = Object.values(
  DUNGEON_CUES,
).flatMap((cue) => cue.files);
